function validate([nums1, nums2, queries]) {
  if (!Array.isArray(nums1) || nums1.length < 1 || nums1.length > 100000) return 'nums1 needs 1 to 10^5 values.';
  if (!Array.isArray(nums2) || nums2.length !== nums1.length) return 'nums1 and nums2 must have the same length.';
  if (nums1.some(v => v !== 0 && v !== 1)) return 'nums1 holds only 0 and 1.';
  if (nums2.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each nums2 value is an integer from 0 to 10^9.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 3 || !query.every(Number.isInteger)) return 'Each query is three integers.';
    const [type, a, b] = query;
    if (type === 1 && !(0 <= a && a <= b && b < nums1.length)) return 'A type 1 query needs 0 <= l <= r < n.';
    if (type === 2 && !(a >= 0 && a <= 1000000 && b === 0)) return 'A type 2 query is [2, p, 0] with 0 <= p <= 10^6.';
    if (type === 3 && !(a === 0 && b === 0)) return 'A type 3 query is [3, 0, 0].';
    if (type < 1 || type > 3) return 'Query types are 1, 2 or 3.';
  }
  return null;
}

