function handleQuery(nums1, nums2, queries) {
  const n = nums1.length;
  const ones = new Array(4 * n).fill(0);
  const pending = new Array(4 * n).fill(false);

  const build = (node, start, end) => {
    if (start === end) {
      ones[node] = nums1[start];
      return;
    }
    const mid = (start + end) >> 1;
    build(2 * node, start, mid);
    build(2 * node + 1, mid + 1, end);
    ones[node] = ones[2 * node] + ones[2 * node + 1];
  };

  const toggle = (node, start, end) => {
    ones[node] = end - start + 1 - ones[node];
    pending[node] = !pending[node];
  };

  const flip = (node, start, end, left, right) => {
    if (right < start || end < left) return;
    if (left <= start && end <= right) {
      toggle(node, start, end);
      return;
    }
    const mid = (start + end) >> 1;
    if (pending[node]) {
      toggle(2 * node, start, mid);
      toggle(2 * node + 1, mid + 1, end);
      pending[node] = false;
    }
    flip(2 * node, start, mid, left, right);
    flip(2 * node + 1, mid + 1, end, left, right);
    ones[node] = ones[2 * node] + ones[2 * node + 1];
  };

  build(1, 0, n - 1);
  let total = nums2.reduce((sum, value) => sum + value, 0);
  const answer = [];
  for (const [type, first, second] of queries) {
    if (type === 1) {
      flip(1, 0, n - 1, first, second);
    } else if (type === 2) {
      total += first * ones[1];
    } else {
      answer.push(total);
    }
  }
  return answer;
}

