function handleQuery(nums1, nums2, queries) {
  // Apply every query to copies of the arrays exactly as described.
  const bits = nums1.slice(), values = nums2.slice(), out = [];
  for (const [type, a, b] of queries) {
    if (type === 1) for (let i = a; i <= b; i++) bits[i] = 1 - bits[i];
    if (type === 2) for (let i = 0; i < values.length; i++) values[i] += bits[i] * a;
    if (type === 3) { let sum = 0; for (const v of values) sum += v; out.push(sum); }
  }
  return out;
}

