function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 6);
  const q = large ? 2000 : 1 + Math.floor(rand() * 8);
  const bigValues = large || rand() < 0.2;
  const nums1 = Array.from({ length: n }, () => (rand() < 0.5 ? 1 : 0));
  const nums2 = Array.from({ length: n }, () => Math.floor(rand() * (bigValues ? 1000000001 : 11)));
  const queries = [];
  for (let i = 0; i < q; i++) {
    const roll = rand();
    if (roll < 0.45) {
      const a = Math.floor(rand() * n), b = Math.floor(rand() * n);
      queries.push([1, Math.min(a, b), Math.max(a, b)]);
    } else if (roll < 0.75) {
      queries.push([2, Math.floor(rand() * (bigValues ? 1000001 : 6)), 0]);
    } else {
      queries.push([3, 0, 0]);
    }
  }
  return [nums1, nums2, queries];
}
